import {STAGES,stageQuote,collectiveGameDay} from './collective.js?v=3.8.0';
import {duoFor} from './collective-state.js?v=3.8.0';
import {canChange} from './commands.js?v=3.8.0';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n||0).toLocaleString('fr-FR',{maximumFractionDigits:2});
const money=n=>num(n)+' €';
const button=(label,action,disabled=false)=>`<button class="secondary" data-action="${action}" ${disabled?'disabled':''}>${esc(label)}</button>`;
const routines={none:'Aucune séance supplémentaire',video:'Vidéo tactique',tactical:'Travail tactique terrain',partners:'Travail avec partenaires'};
const name=(s,id)=>s.players.find(p=>p.id===id)?.name||s.world?.people?.[id]?.name||'Ancien partenaire';
function partnerFields(s,prefix,selected,blocked){
 const ids=s.teams.find(t=>t.id===s.team).roster.filter(id=>id!==s.hero);
 return `<div class="collective-partners">${[0,1].map(i=>`<label>Partenaire ${i+1}${i?' (facultatif)':''}<select id="${prefix}-partner-${i}" ${blocked?'disabled':''}><option value="">Aucun</option>${ids.map(id=>`<option value="${esc(id)}" ${selected[i]===id?'selected':''} ${selected[1-i]===id?'disabled':''}>${esc(name(s,id))}${s.players.find(p=>p.id===id)?.injury?' · blessé':''}</option>`).join('')}</select></label>`).join('')}</div>`;
}
const cost=c=>c.sessions?money(c.price/c.sessions):'—';
const gains=c=>`+${num(c.mastery)} maîtrise · +${num(c.duo)} automatismes (somme des duos)`;
const skips=c=>Object.entries(c.skips).map(([reason,n])=>`${esc(reason)} : ${n}`).join(' · ')||'Aucune';
function stageResult(c){return `<p>${money(c.price)} payés · ${c.sessions} séance(s) effectuée(s) · ${gains(c)}</p><p>Coût par séance : <b>${cost(c)}</b></p><p>Séances sautées / jours non admissibles : ${skips(c)}</p>`;}
export function collectiveView(s,{busy=false,partners=s.collective.partners}={}){
 const e=s.collective,blocked=!canChange(s,{busy}),p=s.players.find(p=>p.id===s.hero),ids=s.teams.find(t=>t.id===s.team).roster.filter(id=>id!==s.hero);
 let next=null;for(let day=s.day+1;day<=s.day+365;day++)if(day%2===0&&!collectiveGameDay(s,day)){next=day;break;}
 const status=s.retired?'Carrière terminée.':p.injury?'Blessure : préparation suspendue.':s.activity==='repos'?'Repos : préparation suspendue.':p.fatigue>65?'Fatigue élevée : séance soumise à la récupération.':e.routine==='none'&&!e.stage?'Aucune préparation supplémentaire activée.':'Préparation selon le calendrier et votre disponibilité.';
 return `<section class="panel collective-panel" id="collective-panel" tabindex="-1"><p class="eyebrow">V3.8 · JOUER ENSEMBLE</p><h2>Préparation collective</h2><div class="stat-strip"><div><strong>${num(s.system)} / 100</strong><span>Maîtrise du système</span></div><div><strong>+${num(s.mastery.sources.collective)}</strong><span>Gains de préparation collective</span></div></div><p>La maîtrise reste personnelle. Les automatismes appartiennent à chaque duo dans ce club, sans modifier les attributs.</p><p class="data-note" role="status">${esc(status)} ${esc(e.notice||'')} ${next?`Prochain créneau pair sans match connu : J${next} (sous réserve de disponibilité).`:''}</p>
 <h3>Ma routine gratuite${e.stage?' · après le stage':''}</h3><p>Choix conservé : <b>${esc(routines[e.routine])}</b>. ${e.stage?'Le stage remplace cette routine pendant sa période ; elle reprend ensuite.':''}</p>${partnerFields(s,'collective',partners,blocked)}<div class="button-row">${Object.entries(routines).map(([id,label])=>button(label,'collective-routine:'+id,blocked||id==='partners'&&!partners.length)).join('')}</div><p class="muted">Vidéo : +0,20 maîtrise brute, sans fatigue. Terrain : +0,35 maîtrise brute et +2 fatigue. Partenaires : +0,50 par duo et +2 fatigue pour vous. Gains amortis près du plafond ; aucun XP d’attribut. Au maximum une séance supplémentaire les jours pairs sans match, après l’entraînement individuel, si votre fatigue est au plus 65 et hors blessure ou repos.</p>
 <h3>Automatismes de duo</h3><p>Une passe réelle entre les deux joueurs peut réduire les pertes de balle et améliorer le tir jusqu’à 0,5 point de pourcentage chacun. Même règle pour les adversaires ; aucun résultat garanti.</p><div class="collective-duos">${ids.map(id=>{const d=duoFor(s,s.team,s.hero,id);return `<article><h4>${esc(name(s,id))}</h4><strong>${num(d?.score)} / 100</strong><p>${num(d?.minutes)} minutes partagées simulées</p><p class="muted">Matchs +${num(d?.sources.match)} · Routine +${num(d?.sources.routine)} · Stages +${num(d?.sources.stage)}</p></article>`;}).join('')}</div>
 <details><summary>24 derniers jours de préparation</summary>${[...e.recent].reverse().map(r=>`<p>J${r.day} · ${esc(routines[r.mode])} · ${r.stageId?'stage #'+r.stageId:'routine'}<br>${r.reason?esc(r.reason):gains(r)+' · +'+r.fatigue+' fatigue'}</p>`).join('')||'<p>Aucune séance traitée.</p>'}</details><details><summary>Duos archivés · ${e.archived.length}</summary><p>Retour dans le même club avec le même partenaire : 75 % du score conservé, une seule fois. Aucun transfert vers un autre club ; 50 duos archivés au maximum.</p>${[...e.archived].reverse().map(d=>`<p>${esc(name(s,d.ids.find(id=>id!==s.hero)))} · ${esc(s.teams.find(t=>t.id===d.team)?.name)} · J${d.closed} · ${num(d.score)} / 100</p>`).join('')}</details>${button('Voir les stages payants','collective-open:stages',busy)}</section>`;
}
export function stagesView(s,{busy=false,quote=null,partners=[]}={}){
 const e=s.collective,c=e.stage,blocked=!canChange(s,{busy});
 return `<section class="panel stages-panel" id="stages-panel" tabindex="-1"><p class="eyebrow">V3.8 · PRÉPARATION RENFORCÉE</p><h2>Stages collectifs</h2><p>Prix fictifs en monnaie du jeu. Un stage à la fois, sans renouvellement automatique. L’entraînement individuel et votre coach personnel continuent.</p><p>Liquidités : ${money(s.money)} · réserve protégée : ${money(s.life.finance.reserve)}.</p><p role="status">${esc(e.notice||'Consultez le devis avant de payer.')}</p>
 ${c?`<article class="coach-active"><h3>${esc(STAGES[c.offerId].name)}</h3><p>J${c.start} à J${c.end} inclus · ${c.estimatedSlots.length} créneaux estimés à l’achat.</p>${c.partners.length?`<p>Partenaires figés : ${c.partners.map(id=>esc(name(s,id))).join(', ')}.</p>`:''}${stageResult(c)}</article>`:`${partnerFields(s,'stage',partners,blocked)}<div class="coach-grid">${Object.entries(STAGES).map(([id,o])=>{const q=stageQuote(s,id,id==='partners'?partners:[]);return `<article><h3>${esc(o.name)}</h3><p class="coach-price">${money(o.price)} <small>/ ${o.days} jours</small></p><p>+${num(o.gain)} ${id==='partners'?'par duo':'maîtrise brute'} par séance admissible, avant amortissement · +${o.fatigue} fatigue.</p>${button('Voir le devis','stage-quote:'+id,blocked)}${!q.ok?`<p class="muted">${esc(q.reason)}</p>`:''}</article>`;}).join('')}</div>`}
 ${quote?`<article class="data-note stage-quote" id="stage-quote" tabindex="-1" aria-label="Devis du stage"><h3>${esc(STAGES[quote.offerId]?.name||'Devis du stage')}</h3><p>Débit immédiat : <b>${money(quote.price)}</b>. Solde après achat : ${money(quote.balanceAfter)} ; réserve : ${money(quote.reserve)}.</p><p>J${quote.start} à J${quote.end} inclus · ${quote.slots.length} créneaux sans match connus : ${quote.slots.map(d=>'J'+d).join(', ')||'aucun'}. Cette estimation ne garantit aucune séance.</p>${quote.partners.length?`<p>Partenaires : ${quote.partners.map(id=>esc(name(s,id))).join(', ')}.</p>`:''}${quote.reason?`<p role="alert">${esc(quote.reason)}</p>`:''}<div class="button-row">${button('Confirmer et payer','stage-confirm',blocked||!quote.ok)}${button('Fermer le devis','stage-dismiss',busy)}</div></article>`:''}
 <p class="muted">Sans remboursement ni prolongation : blessures, fatigue, repos, matchs et partenaires absents peuvent réduire les séances. Un transfert ou la retraite clôt le stage. Aucun achat ne garantit des paniers ou des victoires.</p>${button('Régler ma routine gratuite','collective-open:routine',busy)}<details><summary>Bilan des stages · ${e.history.length} période(s) clôturée(s)</summary><p>Depuis le début : ${money(e.totals.paid)} · ${e.totals.sessions} séances · ${gains(e.totals)}.</p><p class="muted">24 derniers stages détaillés ; les totaux restent conservés.</p>${[...e.history].reverse().map(h=>`<article><h4>${esc(STAGES[h.offerId].name)} · J${h.start}–J${h.end}</h4>${stageResult(h)}<p>${esc(h.reason)}</p></article>`).join('')||'<p>Aucun stage clôturé.</p>'}</details></section>`;
}
export function collectiveMatchSummary(result){
 const c=result?.collective;if(!c)return '<p class="muted">Match joué avec les anciennes règles : aucun effet de duo ajouté rétroactivement.</p>';
 return `<details class="collective-match"><summary>Impact du collectif en match</summary><p>Modificateurs moyens effectivement appliqués, après plafonds, en points de pourcentage. Ils ne permettent d’attribuer aucun panier au collectif.</p>${Object.values(c.effects).map((e,i)=>`<p>${i?'Extérieur':'Domicile'} : ${e.passes} actions servies éligibles · pertes de balle ${num(e.turnoverActions?100*e.turnoverSum/e.turnoverActions:0)} point (${e.turnoverActions} actions) · tir +${num(e.shotActions?100*e.shotSum/e.shotActions:0)} point (${e.shotActions} actions).</p>`).join('')}<p>Duos du joueur : ${(c.duos||[]).map(d=>`${num(d.minutes)} minutes partagées simulées / +${num(d.gain)}`).join(' · ')||'aucune minute partagée'}. Gains attribués après le match, utilisés au prochain coup d’envoi.</p></details>`;
}
